//! M0 parity: rightsizer's cost model, fed the tuner's oracle demands as
//! degenerate distributions, reproduces the tuner's scorer costs
//! (`tuner:bench_all/scoring.py`) on k8s-2-shaped rows within 1%.
//!
//! The fixture (`tests/fixtures/parity_k8s2.json`) is generated by
//! `tests/parity/gen_k8s2_fixture.py`, which imports the tuner's scorer and
//! arms directly. The real k8s-2 rows are not reachable (they live in Union
//! run outputs), so the rows are synthetic but shaped like k8s-2: memory-bench
//! Job pods (mean-cores CPU label), CPU-bench pods with a per-second core
//! series, and GPU pods (sharded or not), scored at the tuner's penalties
//! (OOM 1, delay 1) and the round-23 retry-cost sweep (OOM 5, 20).
//!
//! The comparison runs under [`CostSemantics::Tuner`]; see that type for the
//! three places the tuner's accounting differs from SPEC §7.2. One case is
//! out of scope and reported, not asserted: a GPU task asked to run with no
//! GPU (the tuner retries it on a T4; rightsizer prices a failed start plus
//! one OOM penalty and does not model the platform's retry).

use std::collections::BTreeMap;

use rightsizer_core::cost::{Candidate, CostInputs, CostModel, CostParams, CostSemantics, LadderPlan, MemoryStepper};
use rightsizer_core::grid::{Grid, covering};
use rightsizer_core::normalize::{CellDist, DurationModel, Normalized};
use rightsizer_core::*;
use serde_json::Value;

const FIXTURE: &str = include_str!("fixtures/parity_k8s2.json");

struct Dev {
    accel: AcceleratorId,
    n: u32,
    cap_gib: f64,
    price: f64,
}

fn devices(v: &Value) -> Vec<Dev> {
    v["grids"]["devices"]
        .as_array()
        .unwrap()
        .iter()
        .map(|d| {
            let accel = match d["name"].as_str().unwrap().trim_start_matches(|c: char| c.is_ascii_digit() || c == 'x') {
                "T4" => AcceleratorId::T4_16G,
                "L4" => AcceleratorId::L4_24G,
                "A10G" => AcceleratorId::A10G_24G,
                "L40S" => AcceleratorId::L40S_48G,
                other => panic!("unknown device {other}"),
            };
            let n = d["n"].as_u64().unwrap() as u32;
            Dev { accel, n, cap_gib: n as f64 * d["per_gpu_gib"].as_f64().unwrap(), price: d["price"].as_f64().unwrap() }
        })
        .collect()
}

/// `tuner:bench_gpu/grid.py` `device_for`: the cheapest device whose capacity covers `gib`.
fn device_for(devs: &[Dev], gib: f64) -> usize {
    let fits: Vec<usize> = (0..devs.len()).filter(|&i| devs[i].cap_gib + 1e-9 >= gib).collect();
    if fits.is_empty() {
        return devs.len() - 1;
    }
    *fits.iter().min_by(|&&a, &&b| devs[a].price.total_cmp(&devs[b].price)).unwrap()
}

/// `next_device_up`: the cheapest device with more capacity.
fn next_up(devs: &[Dev], i: usize) -> Option<usize> {
    (0..devs.len()).filter(|&j| devs[j].cap_gib > devs[i].cap_gib).min_by(|&a, &b| devs[a].price.total_cmp(&devs[b].price))
}

struct GridStepper(Vec<f64>);

impl MemoryStepper for GridStepper {
    fn step_to(&self, from: &Candidate, at_least: Bytes) -> Candidate {
        let (i, _) = covering(&self.0, at_least.0 as f64);
        let m = Bytes(self.0[i] as u64);
        Candidate { memory: Some(m), effective_memory: m, ..from.clone() }
    }
}

/// A point mass at `x` that `CellDist::sf` resolves exactly.
fn point(x: f64) -> CellDist {
    CellDist::new(vec![x, x], vec![0.0, 1.0], false, "point").unwrap()
}

/// An empirical distribution whose `expect` is the sample mean: one
/// zero-probability padding cell, then per distinct sample a cell whose
/// geometric midpoint is the sample.
fn empirical(samples: &[f64]) -> CellDist {
    let mut w: BTreeMap<u64, f64> = BTreeMap::new();
    for &s in samples {
        *w.entry(s.max(1e-6).to_bits()).or_default() += 1.0;
    }
    let eps = 1e-9;
    let (mut values, mut probs) = (Vec::new(), Vec::new());
    for (bits, n) in w {
        let s = f64::from_bits(bits);
        values.push(s / (1.0 + eps));
        probs.push(0.0);
        values.push(s * (1.0 + eps));
        probs.push(n);
    }
    CellDist::new(values, probs, false, "series").unwrap()
}

struct Row<'a> {
    v: &'a Value,
}

impl Row<'_> {
    fn f(&self, k: &str) -> f64 {
        self.v[k].as_f64().unwrap_or(f64::NAN)
    }
    fn is_gpu(&self) -> bool {
        self.v["source"] == "gpu"
    }
}

fn gpu_shape(devs: &[Dev], i: usize) -> GpuShape {
    GpuShape { accel: devs[i].accel, count: devs[i].n }
}

/// Rightsizer's cost of the tuner action `(m, c, g)` on a row, under `semantics`.
#[allow(clippy::too_many_arguments)]
fn rightsizer_cost(row: &Row, m: usize, c: usize, g: usize, (oom_penalty, delay_penalty): (f64, f64), semantics: CostSemantics, fx: &Value, devs: &[Dev]) -> f64 {
    let grid = Grid::tuner_v1();
    let mem_vals: Vec<f64> = grid.memory.iter().map(|b| b.0 as f64).collect();
    let gpu_cells: Vec<f64> = fx["grids"]["gpu_gib"].as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect();
    let gpu_task = row.is_gpu();
    let series: Vec<f64> = row.v["cpu_series_json"].as_str().and_then(|s| serde_json::from_str(s).ok()).unwrap_or_default();
    let demand = Normalized {
        kind: EstimateKind::Demand,
        memory: (!gpu_task).then(|| point(row.f("need_mib") * Bytes::MIB as f64)),
        cpu_mean: (!gpu_task).then(|| if series.is_empty() { point(row.f("mean_cores").max(0.05)) } else { empirical(&series) }),
        gpu_memory: gpu_task.then(|| point(row.f("peak_gpu_gib") * Bytes::GIB as f64)),
        parallelism: Parallelism {
            mode: if row.v["sharded"].as_bool().unwrap_or(false) { ParallelismMode::Sharded } else { ParallelismMode::Single },
            imbalance: row.f("gpu_imbalance") as f32,
        },
        duration: DurationModel::default_hour(),
        t_peak_frac: row.f("t_peak_frac"),
    };
    // Shapes: the tuner's m6i.xlarge, and each GPU device as a node whose host
    // CPU and memory come with it (the tuner prices a GPU pod at the instance's price).
    let mut nodes = vec![NodeShape { name: Some("m6i.xlarge".into()), cpu: MilliCpu::cores(4), memory: Bytes::gib(16), gpu: None, price_per_hour: 0.192, host_per_gpu: None }];
    for d in devs {
        nodes.push(NodeShape { name: None, cpu: MilliCpu::cores(100_000), memory: Bytes::gib(1 << 20), gpu: Some(GpuShape { accel: d.accel, count: d.n }), price_per_hour: d.price, host_per_gpu: None });
    }
    let cand_gpu = (g != 0).then(|| gpu_shape(devs, device_for(devs, gpu_cells[g - 1])));
    let cand = if gpu_task {
        Candidate { memory: None, effective_memory: Bytes(0), cpu: None, gpu: cand_gpu, shape: None }
    } else {
        let mb = grid.memory[m];
        Candidate { memory: Some(mb), effective_memory: mb, cpu: Some(grid.cpu[c]), gpu: cand_gpu, shape: None }
    };
    let (om, oc, og) = match row.v["oracle"].as_array() {
        Some(o) => (o[0].as_u64().unwrap() as usize, o[1].as_u64().unwrap() as usize, o[2].as_u64().unwrap() as usize),
        // `scoring.oracle_action` for a CPU task: the label cells, no GPU.
        None => (row.v["label_mem"].as_u64().unwrap() as usize, row.v["label_cpu"].as_u64().unwrap() as usize, 0),
    };
    let oracle = if gpu_task {
        Candidate { memory: None, effective_memory: Bytes(0), cpu: None, gpu: Some(gpu_shape(devs, device_for(devs, gpu_cells[og - 1]))), shape: None }
    } else {
        Candidate { memory: Some(grid.memory[om]), effective_memory: grid.memory[om], cpu: Some(grid.cpu[oc]), gpu: None, shape: None }
    };
    // Ladders: memory ×2 up to 8 attempts (CPU tasks); the next device up, up to 4 attempts (GPU tasks).
    let mut gpu_chain = Vec::new();
    if gpu_task && let Some(GpuShape { accel, count }) = cand_gpu {
        let mut i = devs.iter().position(|d| d.accel == accel && d.n == count).unwrap();
        while gpu_chain.len() < 3 {
            match next_up(devs, i) {
                Some(j) => {
                    gpu_chain.push(gpu_shape(devs, j));
                    i = j;
                }
                None => break,
            }
        }
    }
    let ladder = LadderPlan { factor: 2.0, steps: if gpu_task { gpu_chain.len() as u32 } else { 7 }, final_floor: None, ceiling: *grid.memory.last().unwrap(), gpu_chain };
    let mut platform = PlatformRef::new("k8s");
    platform.retry.ladder = Some(Ladder::caller());
    let prior = Requests::default();
    let (overhead, burn) = if gpu_task { (0.05, 0.02) } else { (0.02, 0.05) };
    let model = CostModel::new(
        CostInputs {
            demand: &demand,
            platform: &platform,
            price: &PriceModel::Packed,
            nodes: &nodes,
            catalog: &[],
            grid: &grid,
            prior: &prior,
            prior_candidate: oracle.clone(),
            staged_bytes: 0.0,
            ladder: Some(ladder),
            params: CostParams {
                penalties: Penalties { oom_penalty, delay_penalty, neighbour_penalty: 0.0 },
                attempt_overhead: overhead,
                no_gpu_fail_hours: 0.05,
                min_burn_frac: burn,
                need_headroom: 1.0,
                semantics,
            },
        },
        std::slice::from_ref(&oracle),
    );
    model.evaluate(&cand, &GridStepper(mem_vals)).expected
}

#[derive(Default)]
struct Tally {
    n: usize,
    max_rel: f64,
    sum_rel: f64,
    within_1pct: usize,
}

impl Tally {
    fn add(&mut self, ours: f64, theirs: f64) {
        let rel = (ours - theirs).abs() / theirs.abs().max(1e-12);
        self.n += 1;
        self.sum_rel += rel;
        self.max_rel = self.max_rel.max(rel);
        self.within_1pct += (rel <= 0.01) as usize;
    }
    fn mean(&self) -> f64 {
        self.sum_rel / self.n.max(1) as f64
    }
}

#[test]
fn decision_rule_reproduces_tuner_scorer_costs_on_k8s2_rows() {
    let fx: Value = serde_json::from_str(FIXTURE).unwrap();
    let devs = devices(&fx);
    let delay = fx["delay_penalty"].as_f64().unwrap();
    let penalties: Vec<(f64, f64)> = fx["penalties"].as_array().unwrap().iter().map(|p| (p.as_f64().unwrap(), delay)).collect();
    let mut by_source: BTreeMap<String, Tally> = BTreeMap::new();
    let mut gap = Tally::default();
    let mut spec_semantics = Tally::default();
    let mut worst = (0.0, String::new());
    for rv in fx["rows"].as_array().unwrap() {
        let row = Row { v: rv };
        for cand in rv["candidates"].as_array().unwrap() {
            let (m, c, g) = (cand["m"].as_u64().unwrap() as usize, cand["c"].as_u64().unwrap() as usize, cand["g"].as_u64().unwrap() as usize);
            for (k, &pen) in penalties.iter().enumerate() {
                let theirs = cand["cost"][k].as_f64().unwrap();
                let ours = rightsizer_cost(&row, m, c, g, pen, CostSemantics::Tuner, &fx, &devs);
                if row.is_gpu() && g == 0 {
                    gap.add(ours, theirs);
                    continue;
                }
                let rel = (ours - theirs).abs() / theirs.abs().max(1e-12);
                if rel > worst.0 {
                    worst = (rel, format!("{} ({m},{c},{g}) oom×{}: ours {ours} tuner {theirs}", rv["run_id"], pen.0));
                }
                by_source.entry(rv["source"].as_str().unwrap().to_string()).or_default().add(ours, theirs);
                spec_semantics.add(rightsizer_cost(&row, m, c, g, pen, CostSemantics::Rightsizer, &fx, &devs), theirs);
            }
        }
    }
    let total: usize = by_source.values().map(|t| t.n).sum();
    for (s, t) in &by_source {
        eprintln!("parity {s}: {} costs, {} within 1%, max rel err {:.2e}, mean {:.2e}", t.n, t.within_1pct, t.max_rel, t.mean());
    }
    eprintln!("parity worst: {:.2e} {}", worst.0, worst.1);
    eprintln!(
        "under SPEC §7.2 semantics instead: {} of {} within 1%, mean rel diff {:.3}, max {:.3}",
        spec_semantics.within_1pct, spec_semantics.n, spec_semantics.mean(), spec_semantics.max_rel
    );
    eprintln!("out of scope (GPU task asked with no GPU): {} costs, mean rel diff {:.3}", gap.n, gap.mean());
    assert!(total > 4000, "fixture too small: {total}");
    for (s, t) in &by_source {
        assert_eq!(t.within_1pct, t.n, "{s}: {} of {} costs off by more than 1% (worst: {})", t.n - t.within_1pct, t.n, worst.1);
    }
}

#[test]
fn oracle_costs_match() {
    let fx: Value = serde_json::from_str(FIXTURE).unwrap();
    let devs = devices(&fx);
    for rv in fx["rows"].as_array().unwrap() {
        let row = Row { v: rv };
        let o = rv["oracle"].as_array().unwrap();
        let (m, c, g) = (o[0].as_u64().unwrap() as usize, o[1].as_u64().unwrap() as usize, o[2].as_u64().unwrap() as usize);
        // The oracle's raw cost (the tuner's `oracle_cost`: no penalties).
        let theirs = rv["oracle_cost"].as_f64().unwrap();
        let ours = rightsizer_cost(&row, m, c, g, (0.0, 0.0), CostSemantics::Tuner, &fx, &devs);
        assert!((ours - theirs).abs() <= 1e-9 * theirs.max(1.0), "{}: ours {ours} tuner {theirs}", rv["run_id"]);
    }
}

// ── rules-sized regret (M0 exit criterion, second half) ─────────────────

fn rs_context(rv: &Value, grid_key: &str) -> WorkloadContext {
    use rightsizer_core::types::*;
    let sizes: BTreeMap<String, u64> = serde_json::from_str(rv["input_bytes_json"].as_str().unwrap()).unwrap();
    let hist: Vec<Value> = serde_json::from_str(rv["history_json"].as_str().unwrap()).unwrap();
    let key = WorkloadKey::parse(&format!("k8s://c/ns/job/{}", grid_key)).unwrap();
    let t0 = chrono::DateTime::from_timestamp(1_800_000_000, 0).unwrap();
    let mut history: Vec<RunRecord> = hist
        .iter()
        .enumerate()
        .map(|(i, h)| {
            let ib: BTreeMap<String, u64> = serde_json::from_value(h["input_bytes"].clone()).unwrap_or_default();
            RunRecord {
                v: 1,
                key: key.clone(),
                cluster: None,
                invocation_id: format!("h{i}"),
                attempt: 1,
                decision_id: None,
                started_at: t0 + chrono::Duration::hours(i as i64),
                inputs: ib.iter().map(|(n, b)| InputMeta::blob(n.clone(), *b)).collect(),
                code_digest: None,
                requested: None,
                origin_prior: None,
                status: RunStatus::Succeeded,
                status_confidence: Confidence::Observed,
                memory_peak: Some(Measurement::exact(h["peak_mem_mib"].as_f64().unwrap() * Bytes::MIB as f64)),
                cpu_mean: h["mean_cores"].as_f64().map(Measurement::exact),
                cpu_peak_window: None,
                cpu_throttled_frac: None,
                gpu_memory_peak: None,
                gpu_util_mean: None,
                t_peak_frac: None,
                duration_s: Some(3600.0),
                staged_bytes: None,
                source: OutcomeSource::Watcher,
                trust: Trust::Verified,
            }
        })
        .collect();
    history.reverse();
    WorkloadContext {
        v: 1,
        key,
        unit: UnitId("main".into()),
        platform: PlatformRef::new("k8s"),
        code: None,
        inputs: sizes.iter().map(|(n, b)| InputMeta::blob(n.clone(), *b)).collect(),
        manifest: ManifestFeatures::default(),
        prior: Prior::default(),
        history,
        labels: BTreeMap::new(),
    }
}

fn regret(r: &[f64]) -> f64 {
    r.iter().sum::<f64>() / r.len().max(1) as f64 - 1.0
}

/// rightsizer's `rules-sized` (with the tuner's tuned knobs: the fixture's
/// `margin`, cold `base` + `k`, `margin_c`), decoded the tuner's way (the
/// cell covering demand × 1.05), scored by the tuner's cost on the fixture's
/// test rows.
///
/// SPEC §7.4 deliberately deviates from the tuner: `scale = max(1, b_now /
/// b_hist)` never scales the nearest run *down*. So the criterion is checked
/// against the tuner's arm with that one rule changed (`pick_scale_floor`,
/// computed by the generator from the tuner's own `_sized_one`), on warm rows
/// (history present), where the two rules are otherwise the same. Cold rows
/// differ by design and are reported: the tuner adds boto3's 48 MiB when the
/// code imports it and parses thread pools for CPU; rightsizer does neither.
#[tokio::test]
async fn rules_sized_reproduces_tuner_regret() {
    use rightsizer_estimators::Estimator;
    use rightsizer_estimators::rules_sized::{ColdStart, RulesSized, RulesSizedParams};
    let fx: Value = serde_json::from_str(FIXTURE).unwrap();
    let devs = devices(&fx);
    let rs = &fx["rules_sized"];
    let k: Vec<f64> = rs["state"]["k"].as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect();
    let params = RulesSizedParams {
        cold: Default::default(),
        cold_default: ColdStart::linear(k[1], k[2]),
        margin: k[0],
        cpu_margin: rs["state"]["static"]["margin_c"].as_f64().unwrap_or(1.0),
        ..RulesSizedParams::default()
    };
    let est = RulesSized::new(params);
    let grid = Grid::tuner_v1();
    let mem_vals: Vec<f64> = grid.memory.iter().map(|b| b.0 as f64).collect();
    let cpu_vals: Vec<f64> = grid.cpu.iter().map(|c| c.as_cores()).collect();
    let cell = |p: &Value| (p[0].as_u64().unwrap() as usize, p[1].as_u64().unwrap() as usize);
    let (mut ours, mut tuner, mut floor) = (Vec::new(), Vec::new(), Vec::new());
    let (mut w_ours, mut w_floor, mut w_agree) = (Vec::new(), Vec::new(), 0);
    let mut declined = 0;
    for rv in rs["rows"].as_array().unwrap() {
        let ctx = rs_context(rv, rv["task_id"].as_str().unwrap().replace(':', "-").as_str());
        let row = Row { v: rv };
        let Ok(e) = est.estimate(&ctx).await else {
            declined += 1;
            continue;
        };
        let norm = rightsizer_core::normalize::normalize(&e, &Grid::rs_grid_v1(), &ctx.history, 0.35).unwrap();
        let m = norm.memory.as_ref().map(|d| covering(&mem_vals, d.median() * 1.05).0).unwrap_or(0);
        let c = norm.cpu_mean.as_ref().map(|d| covering(&cpu_vals, d.median()).0).unwrap_or(3);
        let oc = rv["oracle_cost"].as_f64().unwrap();
        let ratio = |(m, c): (usize, usize)| rightsizer_cost(&row, m, c, 0, (1.0, 1.0), CostSemantics::Tuner, &fx, &devs) / oc;
        let (pt, pf) = (cell(&rv["pick"]), cell(&rv["pick_scale_floor"]));
        ours.push(ratio((m, c)));
        tuner.push(ratio(pt));
        floor.push(ratio(pf));
        if rv["n_history"].as_u64().unwrap() > 0 {
            w_ours.push(ratio((m, c)));
            w_floor.push(ratio(pf));
            w_agree += ((m, c) == pf) as usize;
        }
    }
    let theirs = rs["regret"].as_f64().unwrap();
    eprintln!(
        "rules-sized regret on {} test rows: rightsizer {:.4}; tuner {:.4} (fixture {theirs:.4}); tuner with scale ≥ 1 {:.4}",
        ours.len(),
        regret(&ours),
        regret(&tuner),
        regret(&floor)
    );
    eprintln!("warm rows: {} ({} picks identical): rightsizer {:.4} vs tuner with scale ≥ 1 {:.4}", w_ours.len(), w_agree, regret(&w_ours), regret(&w_floor));
    assert_eq!(declined, 0);
    assert!((regret(&tuner) - theirs).abs() < 1e-6, "the tuner's own picks through rightsizer's cost path");
    assert!((regret(&w_ours) - regret(&w_floor)).abs() <= 0.01, "warm rows: {:.4} vs {:.4}", regret(&w_ours), regret(&w_floor));
    assert!(regret(&ours) <= theirs + 0.01, "rightsizer's rules-sized must not be worse than the tuner's");
}
